module _axi_m_bridge_read_req_fifo
(
  input CLK,
  input RST,
  input _axi_m_bridge_read_req_fifo_enq,
  input [137-1:0] _axi_m_bridge_read_req_fifo_wdata,
  output _axi_m_bridge_read_req_fifo_full,
  output _axi_m_bridge_read_req_fifo_almost_full,
  input _axi_m_bridge_read_req_fifo_deq,
  output [137-1:0] _axi_m_bridge_read_req_fifo_rdata,
  output _axi_m_bridge_read_req_fifo_empty,
  output _axi_m_bridge_read_req_fifo_almost_empty
);

  reg [137-1:0] mem [0:8-1];
  reg [3-1:0] head;
  reg [3-1:0] tail;
  wire is_empty;
  wire is_almost_empty;
  wire is_full;
  wire is_almost_full;
  assign is_empty = head == tail;
  assign is_almost_empty = head == (tail + 1 & 7);
  assign is_full = (head + 1 & 7) == tail;
  assign is_almost_full = (head + 2 & 7) == tail;
  wire [137-1:0] rdata;
  assign _axi_m_bridge_read_req_fifo_full = is_full;
  assign _axi_m_bridge_read_req_fifo_almost_full = is_almost_full || is_full;
  assign _axi_m_bridge_read_req_fifo_empty = is_empty;
  assign _axi_m_bridge_read_req_fifo_almost_empty = is_almost_empty || is_empty;
  assign rdata = mem[tail];
  assign _axi_m_bridge_read_req_fifo_rdata = rdata;

  always @(posedge CLK) begin
    if(RST) begin
      head <= 0;
      tail <= 0;
    end else begin
      if(_axi_m_bridge_read_req_fifo_enq && !is_full) begin
        mem[head] <= _axi_m_bridge_read_req_fifo_wdata;
        head <= head + 1;
      end 
      if(_axi_m_bridge_read_req_fifo_deq && !is_empty) begin
        tail <= tail + 1;
      end 
    end
  end


endmodule



